// The words around the numbers: each quarter's opening, filled from the state by fixed templates. Nothing here is generated by a model,
// so the same run always reads the same, and nothing here can say what the player has not been shown.
import { EVENT_QUARTER, capacity, idleDecision, itemOf, playQuarter } from "./model.ts";
import type { Run } from "./run.ts";
import { PARTIES, lc, termsOf } from "./types.ts";

/** Rupees lakh as a person reads them: 100 lakh is a crore. */
export function money(lakh: number): string {
  const sign = lakh < 0 ? "−" : "";
  const a = Math.abs(lakh);
  return a >= 100 ? `${sign}₹${(a / 100).toFixed(1)} crore` : `${sign}₹${Math.round(a)} lakh`;
}
const profitPhrase = (lakh: number): string => (lakh >= 0 ? `a profit of ${money(lakh)}` : `a loss of ${money(-lakh)}`);
const list = (xs: string[]): string => (xs.length <= 1 ? (xs[0] ?? "") : `${xs.slice(0, -1).join(", ")} and ${xs[xs.length - 1]}`);
const per100 = (x: number): string => (x < 10 ? x.toFixed(1) : String(Math.round(x)));

/** Names a template may use. `per100_<segment id>` is also allowed: of every 100 people who start, how many reach the last stage. */
export const PLACEHOLDERS = [
  "company", "cash", "runway", "hold_profit", "road", "shipped", "profit", "delta", "learned", "pleased",
  "U", "R", "D", "M", "level_label", "trust_eng", "trust_design", "trust_biz", "trust_lead", "trust_ext",
] as const;
export const PER100 = /^per100_([\w]+)$/;

/** The profit this quarter if the player did nothing new, at the briefing's figures. It is what the company reports as its run rate, and it uses no hidden fact. */
export function holdProfit(run: Run): number {
  const w = { ...run.w, expected: { effect: 1, overrun: 1 } };
  return playQuarter(w, run.end, idleDecision(), { evQ: 99 }).r.profit;
}

export function facts(run: Run): Record<string, string> {
  const sc = run.w.cs, s = run.end, last = run.qs[run.qs.length - 1];
  const hold = holdProfit(run);
  const cap = capacity(run.w, s, { ...idleDecision() });
  const out: Record<string, string> = {
    company: sc.company.name,
    cash: money(s.cash),
    hold_profit: profitPhrase(hold),
    runway: hold < 0 ? `about ${Math.max(1, Math.round(s.cash / -hold))} quarters of money` : "the company is not burning cash",
    road: String(Math.round(cap.road)),
    U: String(Math.round(s.U)), R: String(Math.round(s.R)), D: String(Math.round(s.D)), M: String(Math.round(s.M)),
    level_label: sc.measurement[s.level]?.label ?? "",
  };
  for (const p of PARTIES) out[`trust_${p}`] = String(Math.round(s.trust[p]));
  for (const sg of sc.segments) {
    const f = last?.r.funnel[sg.id];
    out[`per100_${sg.id}`] = per100(100 * (f ? f.n3 / Math.max(1, f.n1 / f.s[0]) : sg.stages[0] * sg.stages[1] * sg.stages[2]));
  }
  if (last) {
    const prior = run.qs.length >= 2 ? run.qs[run.qs.length - 2]!.r.profit : holdProfit({ ...run, end: run.start });
    const change = last.r.profit - prior;
    out.shipped = last.r.completed.length ? list(last.r.completed.map((id) => itemOf(sc, id).name)) : "nothing";
    out.profit = money(last.r.profit);
    out.delta = Math.abs(change) < 1 ? "level" : `${change > 0 ? "up" : "down"} ${money(Math.abs(change))}`;
    const dives = last.r.readings.dived.map((id) => {
      const f = sc.hidden.find((x) => x.id === id)!, v = last.s1.known[id]!;
      return `The deep dive on "${f.label}" showed ${f.unit === "multiple" ? `${v.toFixed(2)} times` : `${Math.round(v * 100)}%`}, where the briefing said ${f.unit === "multiple" ? `${f.brief} times` : `${Math.round(f.brief * 100)}%`}.`;
    });
    const tests = last.r.readings.tested.map((id) => `The experiment on ${itemOf(sc, id).name} read about ${money(last.s1.read[id]!)} over two years.`);
    out.learned = [...dives, ...tests].join(" ") || "Nothing new was learned last quarter.";
    const moved = PARTIES.map((p) => ({ p, d: last.s1.trust[p] - last.s0.trust[p] })).filter((x) => Math.abs(x.d) >= 3);
    out.pleased = moved.length
      ? moved.map((x) => `Trust from ${lc(termsOf(sc).parties[x.p])} ${x.d > 0 ? "rose" : "fell"} (${x.d > 0 ? "+" : "−"}${Math.round(Math.abs(x.d))}).`).join(" ")
      : "Nobody's view of you moved much.";
  } else {
    for (const k of ["shipped", "profit", "delta", "learned", "pleased"]) out[k] = "";
  }
  return out;
}

export function render(template: string, f: Record<string, string>): string {
  return template.replace(/\{(\w+)\}/g, (_m, k: string) => {
    if (!(k in f)) throw new Error(`the template names {${k}}, which is not something the engine can say`);
    return f[k]!;
  });
}

/** The title and opening paragraph for the quarter the player is about to play. */
export function opening(run: Run): { n: number; title: string; text: string } {
  const n = run.end.q, brief = run.w.cs.quarters.find((b) => b.n === n);
  if (!brief) throw new Error(`the scenario has no brief for quarter ${n}`);
  return { n, title: brief.title, text: render(brief.opening, facts(run)) };
}

/** Every placeholder name a template in this scenario uses that the engine cannot fill. */
export function unknownPlaceholders(template: string, segmentIds: string[]): string[] {
  const known = new Set<string>([...PLACEHOLDERS, ...segmentIds.map((s) => `per100_${s}`)]);
  return [...template.matchAll(/\{(\w+)\}/g)].map((m) => m[1]!).filter((k) => !known.has(k));
}

export { EVENT_QUARTER };
